command:
// Open Legend Unofficial — Rest All
// Choose the tokens (all targeted or all selected), then one prompt (days + attendant) rests every creature: heals lethal damage and relieves Fatigued.
const { DialogV2 } = foundry.applications.api;
const ol = game.openlegend;
if ( !ol?.groupLethalRest ) {
  ui.notifications?.error("Open Legend Unofficial group helpers are unavailable.");
  return;
}
const selectedCount = canvas.tokens?.controlled?.length ?? 0;
const targetedCount = game.user?.targets?.size ?? 0;
if ( !selectedCount && !targetedCount ) {
  ui.notifications?.warn("Select or target one or more tokens first, then run this macro.");
  return;
}
const mode = await DialogV2.wait({
  window: { title: "Rest All" },
  classes: ["openlegend"],
  content: `
    <div class="form-group">
      <label>Apply to</label>
      <select name="mode" style="flex:1;" autofocus>
        <option value="targeted"${targetedCount ? "" : " disabled"}>All targeted tokens (${targetedCount})</option>
        <option value="selected"${selectedCount ? "" : " disabled"}${targetedCount ? "" : " selected"}>All selected tokens (${selectedCount})</option>
      </select>
    </div>`,
  rejectClose: false,
  buttons: [
    { action: "go", label: "Rest All", icon: "fas fa-bed", default: true,
      callback: (event, button, dialog) => dialog.element.querySelector('select[name="mode"]')?.value ?? "targeted" },
    { action: "cancel", label: "Cancel", icon: "fas fa-times" }
  ]
});
if ( (mode !== "targeted") && (mode !== "selected") ) return;
const tokens = (mode === "selected")
  ? (canvas.tokens?.controlled ?? [])
  : [...(game.user?.targets ?? [])];
if ( !tokens.length ) {
  ui.notifications?.warn(mode === "selected"
    ? "No tokens are selected."
    : "No tokens are targeted.");
  return;
}
await ol.groupLethalRest(tokens);
